# MedOS uninstaller. Generated by MedOS-Setup.exe.
# Removes the program, shortcuts and registry entries. Your content is only
# deleted when you explicitly say no to keeping it.

$ErrorActionPreference = "SilentlyContinue"
Set-Location -LiteralPath $env:TEMP

function Get-MedosInstallDir {
    $dir = $PSScriptRoot
    try {
        $value = (Get-ItemProperty -Path "HKCU:\Software\MedOS" -Name InstallDir -ErrorAction SilentlyContinue).InstallDir
        if ($value -and (Test-Path -LiteralPath $value)) { $dir = $value }
    } catch { }
    return $dir
}

function Remove-MedosPath {
    param([string]$Target)
    if (-not $Target) { return $false }
    $full = $Target
    if ($full.StartsWith("\\?\")) { $full = $full.Substring(4) }
    try { $full = [System.IO.Path]::GetFullPath($full) } catch { }
    $long = "\\?\" + $full
    try {
        if ([System.IO.Directory]::Exists($long)) {
            [System.IO.Directory]::Delete($long, $true)
            return $true
        }
        if ([System.IO.File]::Exists($long)) {
            [System.IO.File]::SetAttributes($long, [System.IO.FileAttributes]::Normal)
            [System.IO.File]::Delete($long)
            return $true
        }
    } catch { }
    return $false
}

$installDir = Get-MedosInstallDir
if (-not (Test-Path -LiteralPath (Join-Path $installDir "START.ps1"))) {
    Write-Host ""
    Write-Host "  MedOS was not found in: $installDir" -ForegroundColor Yellow
    Write-Host ""
    Read-Host "  Press Enter to close"
    exit 1
}

Write-Host ""
Write-Host "  MedOS uninstaller" -ForegroundColor Cyan
Write-Host "  Folder: $installDir"
Write-Host ""
$answer = Read-Host "  Keep your content and settings (books, media, notes, models)? [Y/n]"
$keepContent = -not ($answer -match '^(n|no)$')
Write-Host ""

Write-Host "  Stopping MedOS ..."
$victims = @()
try {
    $victims = Get-CimInstance Win32_Process -ErrorAction Stop | Where-Object {
        $_.ProcessId -ne $PID -and (
            ($_.ExecutablePath -and $_.ExecutablePath.StartsWith($installDir, [System.StringComparison]::OrdinalIgnoreCase)) -or
            (($_.Name -eq 'node.exe' -or $_.Name -eq 'python.exe' -or $_.Name -eq 'pythonw.exe') -and
             $_.CommandLine -and $_.CommandLine.IndexOf($installDir, [System.StringComparison]::OrdinalIgnoreCase) -ge 0)
        )
    }
} catch { }
foreach ($victim in $victims) {
    & taskkill.exe /F /T /PID $victim.ProcessId 2>&1 | Out-Null
}
Start-Sleep -Milliseconds 900

Write-Host "  Removing shortcuts ..."
function Get-ShortcutDir {
    param([string]$Path)
    try {
        if (-not (Test-Path -LiteralPath $Path)) { return $null }
        $shell = New-Object -ComObject WScript.Shell
        $sc = $shell.CreateShortcut($Path)
        if ($sc.WorkingDirectory) { return $sc.WorkingDirectory }
        # Older shortcuts may only carry the quoted launch.vbs argument.
        if ($sc.Arguments -match '"([^"]+)"') {
            return [System.IO.Path]::GetDirectoryName($Matches[1])
        }
    } catch { }
    return $null
}

function Test-OwnedByInstall {
    param([string]$Other)
    if (-not $Other) { return $false }
    try { $a = [System.IO.Path]::GetFullPath($Other).TrimEnd('\') } catch { return $false }
    try { $b = [System.IO.Path]::GetFullPath($installDir).TrimEnd('\') } catch { return $false }
    return $a.Equals($b, [System.StringComparison]::OrdinalIgnoreCase)
}

# Another MedOS folder may own the same shortcut names and registry keys, so
# remove them only when they point at this installation.
try {
    $desktop = [Environment]::GetFolderPath("Desktop")
    $desktopLnk = Join-Path $desktop "MedOS.lnk"
    if ($desktop -and (Test-Path -LiteralPath $desktopLnk)) {
        if (Test-OwnedByInstall (Get-ShortcutDir $desktopLnk)) {
            Remove-Item -LiteralPath $desktopLnk -Force -ErrorAction SilentlyContinue
        } else {
            Write-Host "  Keeping the desktop shortcut: it belongs to another MedOS folder."
        }
    }
} catch { }
try {
    $programs = [Environment]::GetFolderPath("Programs")
    $menuFolder = Join-Path $programs "MedOS"
    if ($programs -and (Test-Path -LiteralPath $menuFolder)) {
        if (Test-OwnedByInstall (Get-ShortcutDir (Join-Path $menuFolder "MedOS.lnk"))) {
            Remove-Item -LiteralPath $menuFolder -Recurse -Force -ErrorAction SilentlyContinue
        } else {
            Write-Host "  Keeping the Start Menu entry: it belongs to another MedOS folder."
        }
    }
} catch { }

Write-Host "  Removing registry entries ..."
try {
    $registered = (Get-ItemProperty -Path "HKCU:\Software\MedOS" -Name InstallDir -ErrorAction SilentlyContinue).InstallDir
    if (Test-OwnedByInstall $registered) {
        Remove-Item -Path "HKCU:\Software\MedOS" -Recurse -Force -ErrorAction SilentlyContinue
        Remove-Item -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\MedOS" -Recurse -Force -ErrorAction SilentlyContinue
    } elseif ($registered) {
        Write-Host "  Keeping the registry entries: they belong to another MedOS folder."
    }
} catch { }

Write-Host "  Removing program files ..."
$programDirs = @("app", "tools", "setup_center", "docs", "linux", "mac", "MedOS.app")
foreach ($name in $programDirs) { Remove-MedosPath (Join-Path $installDir $name) | Out-Null }

$programFiles = @(
    "START.ps1", "START.bat", "STOP.ps1", "STOP.bat", "launch.vbs",
    "ALLOW_LAN.bat", "ALLOW_LAN.ps1", "EXPORT_PROGRESS.bat", "EXPORT_PROGRESS.py",
    "IMPORT_PROGRESS.bat", "IMPORT_PROGRESS.py", "medos.ico", "medos.icns",
    "README.md", "DISTRIBUTION.md", "UPGRADE.md", "PROJECT_STRUCTURE.md",
    "medos_data_manifest.md", "MedOS_USER_GUIDE.md", "MedOS_USER_GUIDE.pdf",
    "MedOS-Phone-README.md", "MedOS-Phone-Install.txt", "MedOS-Companion-README.txt",
    "MedOS-Companion.apk", "MedOS.command", "MedOS-Setup.command", "MedOS-Stop.command",
    "START HERE - LINUX.sh", ".medos-install.json", ".medos-shipped", "Uninstall-MedOS.ps1"
)
foreach ($name in $programFiles) { Remove-MedosPath (Join-Path $installDir $name) | Out-Null }

if (-not $keepContent) {
    Write-Host "  Removing content and settings ..."
    foreach ($name in @("data", "models", "exports")) {
        Remove-MedosPath (Join-Path $installDir $name) | Out-Null
    }
    Remove-MedosPath (Join-Path $env:LOCALAPPDATA "MedOS") | Out-Null
    Remove-MedosPath $installDir | Out-Null
    if ([System.IO.Directory]::Exists("\\?\" + $installDir)) {
        $command = "timeout /t 2 /nobreak >nul & rmdir /s /q ""$installDir"""
        Start-Process -WindowStyle Hidden -FilePath $env:ComSpec -ArgumentList "/c $command"
    }
}

Write-Host ""
if ($keepContent) {
    Write-Host "  MedOS has been uninstalled." -ForegroundColor Green
    Write-Host "  Your content is still in: $installDir"
} else {
    Write-Host "  MedOS and its content have been removed." -ForegroundColor Green
}
Write-Host ""
Read-Host "  Press Enter to close"
